// Generated by python -m ml_bridge.export_contract; optional bridge only.
// Power kW, storage kWh, SOC fractions, UTC timestamps, elapsed hours.

export type Assessment = { "bridge_schema_version"?: "lastlight-ml-bridge-1"; "physics": SimulationResult; "neural": NeuralAnalysis; "physics_authoritative"?: true; "engineering_clearance"?: false }

export type AssessmentRequest = { "scenario": SimulationRequest; "physics_version"?: "lastlight-dispatch-1.0.0"; "schema_version"?: "1.0.0"; "feature_schema"?: "lastlight-official-v1-features-1" }

export type Battery = { "capacity_kwh"?: number; "initial_soc"?: number; "minimum_soc"?: number; "maximum_soc"?: number; "charge_efficiency"?: number; "discharge_efficiency"?: number; "max_charge_kw"?: number; "max_discharge_kw"?: number }

export type CandidatePoint = { "initial_soc": number; "duration_hours": number }

export type CandidateRequest = { "scenario": SimulationRequest; "physics_version"?: "lastlight-dispatch-1.0.0"; "schema_version"?: "1.0.0"; "feature_schema"?: "lastlight-official-v1-features-1"; "points": Array<CandidatePoint>; "limit"?: number }

export type CandidateResult = { "bridge_schema_version"?: "lastlight-ml-bridge-1"; "physics_version"?: "lastlight-dispatch-1.0.0"; "schema_version"?: "1.0.0"; "neural_status": "available" | "unavailable" | "incompatible_checkpoint"; "neural_model_version": string | null; "candidates": Array<VerifiedCandidate>; "warnings": Array<string> }

export type Grid = { "online"?: boolean; "profile_online"?: Array<boolean> | null; "import_limit_kw"?: number; "charge_battery"?: boolean }

export type HTTPValidationError = { "detail"?: Array<ValidationError> }

export type Inverter = { "max_kw"?: number; "islanding_capable"?: boolean }

export type Load = { "critical_kw"?: number; "noncritical_kw"?: number; "shed_noncritical_during_outage"?: boolean }

export type NeuralAnalysis = { "status": "available" | "unavailable" | "incompatible_checkpoint"; "model_version"?: string | null; "feature_schema"?: string; "source_physics_version"?: string | null; "estimate"?: NeuralEstimate | null; "warnings": Array<string> }

export type NeuralEstimate = { "predicted_failure": boolean; "synthetic_failure_score": number; "outside_training_domain": boolean; "high_uncertainty": boolean; "physics_required"?: true; "engineering_clearance"?: false }

export type Provenance = { "category"?: "measured" | "research_derived" | "synthetic"; "references"?: Array<string> }

export type SimulationRequest = { "start_utc"?: string; "duration_hours"?: number; "step_minutes"?: number; "seed"?: number; "battery"?: Battery; "inverter"?: Inverter; "load"?: Load; "solar"?: Solar; "grid"?: Grid; "provenance"?: Provenance }

export type SimulationResult = { "run_id": string; "model_version"?: string; "input_hash": string; "seed": number; "summary": SimulationSummary; "trace": Array<SimulationTracePoint>; "provenance": Provenance; "schema_version"?: string; "input": SimulationRequest; "warnings": Array<string> }

export type SimulationSummary = { "critical_survival_hours": number | null; "served_critical_fraction": number; "unserved_critical_kwh": number; "first_failure_utc": string | null; "max_balance_residual_kwh": number; "observed_duration_hours": number; "survived_full_window": boolean; "idealized_autonomy_hours": number | null; "total_critical_demand_kwh": number; "served_critical_kwh": number; "served_noncritical_kwh": number; "unserved_noncritical_kwh": number; "grid_import_kwh": number; "solar_available_kwh": number; "solar_used_kwh": number; "solar_curtailed_kwh": number; "battery_charge_kwh": number; "battery_discharge_kwh": number; "conversion_loss_kwh": number; "initial_battery_energy_kwh": number; "final_battery_energy_kwh": number; "usable_capacity_kwh": number; "ending_soc": number; "cumulative_balance_residual_kwh": number }

export type SimulationTracePoint = { "t_utc": string; "grid_kw": number; "solar_kw": number; "battery_charge_kw": number; "battery_discharge_kw": number; "battery_soc": number; "critical_served_kw": number; "critical_demand_kw": number; "noncritical_served_kw": number; "unserved_critical_kw": number; "status": "normal" | "islanded" | "degraded" | "critical_failure"; "t_end_utc": string; "elapsed_hours": number; "duration_hours": number; "grid_online": boolean; "solar_available_kw": number; "solar_curtailed_kw": number; "grid_charge_kw": number; "noncritical_demand_kw": number; "unserved_noncritical_kw": number; "battery_soc_end": number; "battery_energy_kwh": number; "battery_energy_end_kwh": number; "conversion_loss_kwh": number; "ac_balance_residual_kwh": number; "storage_balance_residual_kwh": number; "balance_residual_kwh": number }

export type Solar = { "generation_kw"?: number; "profile_kw"?: Array<number> | null; "islanding_capable"?: boolean }

export type ValidationError = { "loc": Array<string | number>; "msg": string; "type": string; "input"?: unknown; "ctx"?: Record<string, unknown> }

export type VerifiedCandidate = { "initial_soc": number; "duration_hours": number; "neural": NeuralEstimate; "physics_verified"?: true; "physics_model_version"?: "lastlight-dispatch-1.0.0"; "physics_schema_version"?: "1.0.0"; "physics_run_id": string; "input_hash": string; "physics_summary": SimulationSummary; "warnings": Array<string> }
